code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    marker = None
    for r in range(h):
        if len(set(grid[r])) == 1 and grid[r][0] != background:
            marker = ("row", r, grid[r][0])
            break
    if marker is None:
        for c in range(w):
            if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != background:
                marker = ("col", c, grid[0][c])
                break
    if marker is None:
        return [row[:] for row in grid]

    axis, pos, marker_color = marker
    object_colors = [color for color in counts if color not in (background, marker_color)]
    if not object_colors:
        return [row[:] for row in grid]
    obj = max(object_colors, key=lambda color: counts[color])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == obj]
    out = [row[:] for row in grid]

    if axis == "row":
        lo, hi = min(r for r, c in cells), max(r for r, c in cells)
        direction = 1 if lo > pos else -1
        line = pos + direction * (hi - lo + 2)
        # When the guide stripe is interior, the isolated 9 marker is shifted
        # beside it before the parallel 8 line is drawn.
        if obj == 9 and 0 < pos < h - 1:
            target = pos + direction
            delta = target - (lo if direction > 0 else hi)
            for r, c in cells:
                out[r][c] = background
            for r, c in cells:
                out[r + delta][c] = obj
        if 0 <= line < h:
            out[line] = [8] * w
    else:
        lo, hi = min(c for r, c in cells), max(c for r, c in cells)
        direction = 1 if lo > pos else -1
        line = pos + direction * (hi - lo + 2)
        if obj == 9 and 0 < pos < w - 1:
            target = pos + direction
            delta = target - (lo if direction > 0 else hi)
            for r, c in cells:
                out[r][c] = background
            for r, c in cells:
                out[r][c + delta] = obj
        if 0 <= line < w:
            for r in range(h):
                out[r][line] = 8
    return out
'''
